/* @lc app=leetcode id=3537 lang=kotlin */ class Solution { fun specialGrid(n: Int): Array<IntArray> = if (n == 0) arrayOf(intArrayOf(0)) else specialGrid(n - 1).let { q -> (1 shl (n - 1)).let { s -> (s * s).let { a -> Array(2 * s) { i -> IntArray(2 * s) { j -> if (i < s && j >= s) q[i][j - s] else if (i >= s && j >= s) q[i - s][j - s] + a else if (i >= s && j < s) q[i - s][j] + 2 * a else q[i][j] + 3 * a } } } } } }